const stories={culture:{label:'POP CULTURE / EPISODE CONCEPT',title:'When did our personality become a personal brand?',paragraphs:['Somewhere between getting dressed and posting the outfit, being yourself acquired an audience. This episode idea asks what happens when taste becomes a strategy and every interest needs to fit an aesthetic.','The conversation: inspiration versus imitation, fashion as play, and the things we might still love if nobody were watching.','This is a preview of the editorial direction. The finished episode and its YouTube link will appear here when published.']},ideas:{label:'BIG IDEAS / EPISODE CONCEPT',title:'Ambition looks good on you. But at what cost?',paragraphs:['Wanting a bigger life can be exciting. It can also make the life you have feel like a waiting room.','This episode idea explores ambition, comparison, and the pressure to make every hour count. Can we build something meaningful without treating ourselves like an unfinished product?','This is a preview of the editorial direction. The finished episode and its YouTube link will appear here when published.']},life:{label:'LIFE, DECODED / EPISODE CONCEPT',title:'The plot twist is that you’re allowed to begin again.',paragraphs:['Fresh starts rarely come with a dramatic soundtrack. Sometimes they look like sending a message, showing up, or trying again on an ordinary Tuesday.','This episode idea is about friendships, changing your mind, and leaving room for a version of yourself you haven’t met yet.','This is a preview of the editorial direction. The finished episode and its YouTube link will appear here when published.']},reading:{label:'MARGIN NOTES / OPENING EDITORIAL DRAFT',title:'You can be a work in progress and still have something to say.',paragraphs:['There is a particular kind of procrastination that looks very responsible: waiting until you know enough to begin. You collect references, make another plan, and tell yourself that confidence will arrive before the first step.','But a voice is something you develop by using it. A first attempt doesn’t have to hold your entire identity. It can be a small, honest thing: a question you care about, a thought you haven’t finished, a conversation worth starting.','That is the idea behind this little corner of the internet. A place to be curious out loud. To laugh, reconsider, and sometimes say: actually, I think differently now.','Start with what you have. Leave room to change. The interesting part is usually in the margins.']}};
const filters=[...document.querySelectorAll('[data-filter]')];filters.forEach(button=>button.addEventListener('click',()=>{filters.forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});document.querySelectorAll('[data-category]').forEach(card=>card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter)}));
const dialog=document.querySelector('#story-dialog');document.querySelectorAll('[data-story]').forEach(button=>button.addEventListener('click',()=>{const story=stories[button.dataset.story];document.querySelector('#story-label').textContent=story.label;document.querySelector('#story-title').textContent=story.title;const body=document.querySelector('#story-body');body.replaceChildren(...story.paragraphs.map(text=>{const p=document.createElement('p');p.textContent=text;return p}));dialog.showModal()}));document.querySelector('#close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()});
const notes={chaotic:'“Behen, you don’t need a whole new life tonight. A glass of water and one small decision will do.”',stuck:'“A messy first page is still a first page. Give yourself something to edit.”',main:'“Wear the outfit. Ask the question. Your life is allowed to happen before you feel ready.”'};document.querySelectorAll('[data-mood]').forEach(button=>{button.setAttribute('aria-pressed','false');button.addEventListener('click',()=>{document.querySelectorAll('[data-mood]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelector('#napkin').textContent=notes[button.dataset.mood]})});
